const message = $('Receive Telegram message').item.json;
const cfg = $('Set config').item.json;

// Extract message text and chat info
const text = (message.message?.text || message.text || '').trim();
const chatId = String(message.message?.chat?.id || message.chat?.id || '');
const fromUsername = message.message?.from?.username || message.message?.from?.first_name || 'User';

// Extract URL from message text
const urlRegex = /(https?:\/\/[^\s]+)/i;
const urlMatch = text.match(urlRegex);
let extractedUrl = urlMatch ? urlMatch[1].trim() : null;

// Clean up common URL trailing punctuation
if (extractedUrl) {
  extractedUrl = extractedUrl.replace(/[.,!?)]+$/, '');
}

const hasUrl = !!extractedUrl && extractedUrl.startsWith('http');

// Help message shown when user sends anything other than a URL
const helpMessage =
  'Hi ' + fromUsername + '! I am your Website Audit Bot.\n\n' +
  'Send me any website URL and I will analyze it instantly.\n\n' +
  'Example:\nhttps://example.com\n\n' +
  'I will send back:\n' +
  '- Overall score out of 10\n' +
  '- Top 3 critical issues\n' +
  '- 3 quick wins\n' +
  '- Key recommendation\n' +
  '- Opportunity estimate\n' +
  '- 3 sales talking points\n\n' +
  'Just paste any website URL to get started.';

return [{
  json: {
    hasUrl,
    websiteUrl: extractedUrl || '',
    originalText: text,
    chatId,
    fromUsername,
    helpMessage,
    sheetId: cfg.sheetId,
    sheetName: cfg.sheetName,
    senderName: cfg.senderName,
    today: cfg.today
  }
}];

const html = $input.first().json;
const parseData = $('Find a URL in the message').item.json;

// Get raw HTML as string
let rawHtml = '';
try {
  rawHtml = typeof html === 'string' ? html : (html?.data || '');
} catch (e) {
  rawHtml = '';
}

// Handle scraping failure gracefully
if (!rawHtml || rawHtml.length < 100 || html?.error || html?.code) {
  return [{
    json: {
      ...parseData,
      pageContent: 'Could not fetch content from ' + parseData.websiteUrl + '. The website may be blocking automated requests.',
      contentLength: 0,
      scrapeFailed: true
    }
  }];
}

// Clean HTML — remove scripts, styles, nav, footer
let cleanText = rawHtml
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<\/(div|p|li|h[1-6]|section|article)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/\s{3,}/g, '\n\n')
  .trim()
  .substring(0, 4000);

return [{
  json: {
    ...parseData,
    pageContent: cleanText,
    contentLength: cleanText.length,
    scrapeFailed: false
  }
}];

const analysis = $input.first().json.output;
const pageData = $('Strip the HTML down to text').item.json;

// Safe fallback if GPT parsing failed
if (!analysis) {
  return [{
    json: {
      auditMessage: 'Sorry, I could not analyze this website. Please try again with a different URL.',
      chatId: pageData.chatId,
      websiteUrl: pageData.websiteUrl,
      overallScore: 'N/A',
      businessType: 'Unknown',
      topIssues: 'Analysis failed',
      topWins: 'Analysis failed',
      keyRecommendation: 'Analysis failed',
      today: pageData.today,
      sheetId: pageData.sheetId,
      sheetName: pageData.sheetName,
      fromUsername: pageData.fromUsername,
      loggedAt: new Date().toISOString().replace('T', ' ').substring(0, 16)
    }
  }];
}

const score = analysis.overallScore || 0;
const scoreLabel = score >= 8 ? 'Good' : score >= 5 ? 'Needs Work' : 'Critical';

const critIssues = (analysis.criticalIssues || []).map((issue, i) => (i + 1) + '. ' + issue).join('\n');
const quickWins = (analysis.quickWins || []).map((win, i) => (i + 1) + '. ' + win).join('\n');
const talkingPoints = (analysis.talkingPoints || []).map((pt, i) => (i + 1) + '. ' + pt).join('\n');

// Format clean Telegram message — no emojis, plain text
const auditMessage =
  'WEBSITE AUDIT COMPLETE\n\n' +
  'URL: ' + pageData.websiteUrl + '\n' +
  'Score: ' + score + ' out of 10 — ' + scoreLabel + '\n' +
  'Business: ' + (analysis.businessType || 'Unknown') + '\n\n' +
  '--- TOP 3 ISSUES ---\n' +
  critIssues + '\n\n' +
  '--- QUICK WINS ---\n' +
  quickWins + '\n\n' +
  '--- KEY RECOMMENDATION ---\n' +
  (analysis.keyRecommendation || 'Not available') + '\n\n' +
  '--- OPPORTUNITY (3-6 months) ---\n' +
  (analysis.estimatedOpportunity || 'Not available') + '\n\n' +
  '--- SALES TALKING POINTS ---\n' +
  talkingPoints;

const loggedAt = new Date().toISOString().replace('T', ' ').substring(0, 16);

return [{
  json: {
    auditMessage,
    chatId: pageData.chatId,
    websiteUrl: pageData.websiteUrl,
    overallScore: score + ' out of 10',
    businessType: analysis.businessType || 'Unknown',
    topIssues: (analysis.criticalIssues || []).join(' | '),
    topWins: (analysis.quickWins || []).join(' | '),
    keyRecommendation: analysis.keyRecommendation || '',
    today: pageData.today,
    sheetId: pageData.sheetId,
    sheetName: pageData.sheetName,
    fromUsername: pageData.fromUsername,
    loggedAt
  }
}];
